diff --git a/engine/render/src/shaders/ir_selected_shape_receiver.glsl b/engine/render/src/shaders/ir_selected_shape_receiver.glsl
index 9f9373cb6..42c114829 100644
--- a/engine/render/src/shaders/ir_selected_shape_receiver.glsl
+++ b/engine/render/src/shaders/ir_selected_shape_receiver.glsl
@@ -1,3 +1,8 @@
+// Continuous fragment rays use the producer Z-face origin, not the texture center.
+vec2 shapeFragmentQueryPixel(vec2 rawCanvasPixel, ivec2 canvasSize) {
+    return rawCanvasPixel - 0.5 * vec2(canvasSize) + vec2(trixelOriginOffsetZ1(canvasSize));
+}
+
 layout(std140, binding = 23) uniform ShapeReceiverFrame {
     ShapeProjectionData receiverFrame;
 };
diff --git a/engine/render/src/shaders/ir_trixel_to_framebuffer_body.glsl b/engine/render/src/shaders/ir_trixel_to_framebuffer_body.glsl
index 7b5859198..333a2e763 100644
--- a/engine/render/src/shaders/ir_trixel_to_framebuffer_body.glsl
+++ b/engine/render/src/shaders/ir_trixel_to_framebuffer_body.glsl
@@ -99,7 +99,8 @@ void main() {
 #if IR_SHAPE_RECEIVER && !IR_SHAPE_LIGHTING
     if (color.a >= 0.1) {
         vec3 position = vec3(0.0), normal = vec3(0.0);
-        if (selectedShapeBoxReceiver(sampleCoord, textureSize.x, originRaw, true,
+        if (selectedShapeBoxReceiver(sampleCoord, textureSize.x,
+                                     shapeFragmentQueryPixel(originRaw, textureSize), true,
                                      position, normal)) {
             float visibility = shadowsEnabled == 0 ? 1.0 :
                 worldShapeSurfaceSunShadowFactor(position, normal, shapeCanvasIsoDepth(position, receiverFrame),
@@ -113,7 +114,8 @@ void main() {
 #if IR_SHAPE_LIGHTING
     if (color.a >= 0.1 && lightingEnabled != 0) {
         vec3 position = vec3(0.0), normal = vec3(0.0);
-        if (selectedShapeBoxReceiver(sampleCoord, textureSize.x, originRaw, true,
+        if (selectedShapeBoxReceiver(sampleCoord, textureSize.x,
+                                     shapeFragmentQueryPixel(originRaw, textureSize), true,
                                      position, normal))
             color.rgb = shapeSurfaceLighting(sampleCoord, textureSize.x, position, normal,
                 shapeCanvasIsoDepth(position, receiverFrame), casterViewToWorld, color.rgb);
